sys_variable_value.value:
(function execute(inputs, outputs) {
    var jsonString = inputs.travel_alerts;
    try {
        var newAlertCount = 0;
        var alertArray = JSON.parse(jsonString);

        var exist_alert = new GlideRecord('x_snc_duty_travel_alerts');
        exist_alert.addEncodedQuery('duty_travel_req='+inputs.dt_req.sys_id);
        exist_alert.setLimit(10);
        exist_alert.query();
        while(exist_alert.next()) exist_alert.deleteRecord();

        for (var i = 0; i < alertArray.length; i++) {
            /*var exist_alert = new GlideRecord('x_snc_duty_travel_alerts');
            exist_alert.addEncodedQuery('duty_travel_req='+inputs.dt_req.sys_id+'^ota='+alertArray[i].alert_sysid);
            exist_alert.setLimit(10);
            exist_alert.query();
            while(exist_alert.next()) exist_alert.deleteRecord();*/
            //if(!exist_alert.next()) {
                var alert = new GlideRecord('x_snc_duty_travel_alerts');
                alert.initialize();
                alert.setValue('alert', alertArray[i].alert_description);
                alert.setValue('duty_travel_req', inputs.dt_req.sys_id);
                alert.setValue('ota', alertArray[i].alert_sysid);
                alert.insert();
                newAlertCount+=1;
            //}
        }
        if(newAlertCount == 0)
            outputs.result = 'There are no outbound travel alerts at this time.';
        else
            outputs.result = '[code]⚠️ '+newAlertCount+' outbound travel alerts identified for <b>'+inputs.dt_req.going_to.getDisplayValue()+'</b>. Please check the <b>Duty Travel Alerts</b> tab for additional travel advisory.[/code]';
    }
    catch(e) {
        outputs.result = 'Unable to retrieve outbound travel alerts.'
    }
})(inputs, outputs);

